import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Verzeichnis aller Rassen","description":"","frontmatter":{},"headers":[],"relativePath":"de/94-万族名录.md","filePath":"de/94-万族名录.md","lastUpdated":null}'),s={name:"de/94-万族名录.md"};function a(d,e,h,u,l,o){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="verzeichnis-aller-rassen" tabindex="-1">Verzeichnis aller Rassen <a class="header-anchor" href="#verzeichnis-aller-rassen" aria-label="Permalink to &quot;Verzeichnis aller Rassen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>94</td></tr><tr><td>Modul</td><td>Anhänge und Referenzmaterialien</td></tr><tr><td>Schlüsselwörter</td><td>Verzeichnis aller Rassen, Rassenklassifikation, intelligente Rassen, Rassenmerkmale, Republik aller Rassen</td></tr></tbody></table><h2 id="_1-beschreibung-des-verzeichnisses" tabindex="-1">1. Beschreibung des Verzeichnisses <a class="header-anchor" href="#_1-beschreibung-des-verzeichnisses" aria-label="Permalink to &quot;1. Beschreibung des Verzeichnisses&quot;">​</a></h2><p>Dieses Verzeichnis enthält die wichtigsten bekannten intelligenten Rassen innerhalb des Rahmens der Anker-Symbiose-Zivilisation (Republik aller Rassen), klassifiziert und organisiert nach Lebensform und Evolutionspfad. Jede Rasse listet Rassenname, Lebensform, Kernmerkmale, kulturelle Merkmale und Position in der Symbiose-Zivilisation auf. Dieses Verzeichnis ist ein dynamisches Aktualisierungsdokument; mit der Vertiefung der Erkundung zwischen Ebenen werden neu entdeckte Rassen kontinuierlich hinzugefügt. Das Grundprinzip der Republik aller Rassen ist: Alle intelligenten Rassen, unabhängig von ihrer Form oder ihrem Kultivierungsniveau, sind vor dem Gesetz gleich und genießen alle Rechte, die die Symbiose-Zivilisation gewährt.</p><h2 id="_2-ubersicht-der-rassenklassifikation" tabindex="-1">2. Übersicht der Rassenklassifikation <a class="header-anchor" href="#_2-ubersicht-der-rassenklassifikation" aria-label="Permalink to &quot;2. Übersicht der Rassenklassifikation&quot;">​</a></h2><p>Die intelligenten Rassen in Hengyuanzhou werden nach den grundlegenden Merkmalen ihrer Lebensform in die folgenden acht Hauptkategorien unterteilt:</p><table tabindex="0"><thead><tr><th>Kategorie</th><th>Merkmale der Lebensform</th><th>Anzahl bekannter Rassen (ca.)</th><th>Repräsentative Rassen</th></tr></thead><tbody><tr><td>Humanoide Form</td><td>Menschliche Körperstruktur, aufrecht gehend auf zwei Beinen, hoch entwickeltes Gehirn</td><td>Ca. 3.000 Arten</td><td>Menschenrasse, Elfenrasse, Zwergenrasse</td></tr><tr><td>Tierische Form</td><td>Tierische Körpermerkmale, kann Transformationsfähigkeit haben oder nicht</td><td>Ca. 5.000 Arten</td><td>Drachenrasse, Phönixrasse, Werwolf-Rasse</td></tr><tr><td>Pflanzliche Form</td><td>Pflanze als grundlegende Lebensform, besitzt Bewusstsein und Bewegungsfähigkeit</td><td>Ca. 800 Arten</td><td>Baumgeist-Rasse, Blumengeist-Rasse, Ranken-Rasse</td></tr><tr><td>Elementare Form</td><td>Natürliche Elemente als Körperzusammensetzung, keine feste materielle Form</td><td>Ca. 1.200 Arten</td><td>Feuerelement-Rasse, Wasserelement-Rasse, Luftelement-Rasse</td></tr><tr><td>Energetische Form</td><td>Reine Energie als Existenzform, kein materieller Körper</td><td>Ca. 600 Arten</td><td>Lichtgeist-Rasse, Dunkelenergie-Rasse, Donner-Rasse</td></tr><tr><td>Bewusste Form</td><td>Reines Bewusstsein als Existenzform, nicht abhängig von materiellem Träger</td><td>Ca. 300 Arten</td><td>Bewusstseinswesen-Rasse, Kollektivbewusstseins-Rasse, Leerengeist-Rasse</td></tr><tr><td>Mechanische Form</td><td>Mechanische oder digitale Struktur als Lebensträger, besitzt autonomes Bewusstsein</td><td>Ca. 400 Arten</td><td>Mechanische Rasse, digitales Leben-Rasse, Cyber-Rasse</td></tr><tr><td>Gemischte Form</td><td>Spezielle Rassen, die aus einer Mischung von zwei oder mehr Lebensformen bestehen</td><td>Ca. 700 Arten</td><td>Halbmechanische Rasse, Element-Tier-Rasse, Pflanzen-Elfen-Rasse</td></tr></tbody></table><h2 id="_3-detaillierte-aufzeichnung-der-hauptrassen" tabindex="-1">3. Detaillierte Aufzeichnung der Hauptrassen <a class="header-anchor" href="#_3-detaillierte-aufzeichnung-der-hauptrassen" aria-label="Permalink to &quot;3. Detaillierte Aufzeichnung der Hauptrassen&quot;">​</a></h2><h3 id="_3-1-humanoide-form" tabindex="-1">3.1 Humanoide Form <a class="header-anchor" href="#_3-1-humanoide-form" aria-label="Permalink to &quot;3.1 Humanoide Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rassenname</th><th>Kernmerkmale</th><th>Kulturelle Merkmale</th><th>Position in der Symbiose-Zivilisation</th></tr></thead><tbody><tr><td>Menschenrasse</td><td>Extrem starke Anpassungsfähigkeit, hervorragende Lernfähigkeit, mittlere Fortpflanzungsfähigkeit, durchschnittliche Lebenserwartung 80-120 Jahre</td><td>Extrem hohe kulturelle Vielfalt, erfahren in sozialer Organisation und institutionellem Aufbau</td><td>Eine der Kernrassen der Symbiose-Zivilisation, größter Bevölkerungsanteil, spielt dominante Rolle in Governance und Kultur</td></tr><tr><td>Elfenrasse</td><td>Extrem lange Lebenserwartung (durchschnittlich über 500 Jahre), hohe Affinität zu natürlicher Energie, schönes Aussehen</td><td>Verehrt Natur und Kunst, Kultur elegant und raffiniert, erfahren in Magie und Bogenschießen</td><td>Kultureller und künstlerischer Pfeiler der Symbiose-Zivilisation, herausragender Beitrag in Umweltschutz und Ästhetik</td></tr><tr><td>Zwergenrasse</td><td>Kleinwüchsig aber kräftig, angeborene Affinität zu Metallen und Mineralien, Lebenserwartung ca. 300 Jahre</td><td>Schätzt Handwerk und Schmiedekunst, Kultur einfach und solide, erfahren in Ingenieurwesen und Bauwesen</td><td>Ingenieurtechnischer Fertigungspfeiler der Symbiose-Zivilisation, unersetzlich im Infrastrukturbau und der Schmiedekunst von Artefakten</td></tr><tr><td>Riesenrasse</td><td>Riesiger Körperbau (durchschnittliche Körpergröße über 5 Meter), extrem starke Kraft, Lebenserwartung ca. 200 Jahre</td><td>Verehrt Kraft und Ehre, Kultur rauh und heldenhaft, erfahren in Schwerarbeit und Kampf</td><td>Schwerarbeits- und Verteidigungskraft der Symbiose-Zivilisation, spielt wichtige Rolle bei Großprojekten und Ebenenverteidigung</td></tr><tr><td>Gnomrasse</td><td>Extrem kleinwüchsig (durchschnittliche Körpergröße unter 1 Meter), extrem hohe Intelligenz, Talent für Mechanik und Erfindung</td><td>Schätzt Wissen und Innovation, Kultur lebhaft und fröhlich, erfahren in technologischer Erfindung</td><td>Technologische Innovationskraft der Symbiose-Zivilisation, fruchtbar auf dem Gebiet der technologischen Forschung und Entwicklung sowie Erfindung</td></tr></tbody></table><h3 id="_3-2-tierische-form" tabindex="-1">3.2 Tierische Form <a class="header-anchor" href="#_3-2-tierische-form" aria-label="Permalink to &quot;3.2 Tierische Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rassenname</th><th>Kernmerkmale</th><th>Kulturelle Merkmale</th><th>Position in der Symbiose-Zivilisation</th></tr></thead><tbody><tr><td>Drachenrasse</td><td>Extrem lange Lebenserwartung (Tausende von Jahren), extrem hohes Talent für Kraft und Magie, kann in menschliche Form wechseln</td><td>Verehrt Kraft und Weisheit, Kultur stolz und tiefgründig, erfahren in Vermögensanhäufung und Wissensbewahrung</td><td>Hochklassige Kampfkraft und Wissenshüterin der Symbiose-Zivilisation, respektierte Position in der Ebenenverteidigung und Bewahrung alter Bücher</td></tr><tr><td>Phönixrasse</td><td>Besitzt Fähigkeit zur Nirvana-Wiedergeburt, extrem hohe Affinität zum Feuerelement, kann in menschliche Form wechseln</td><td>Verehrt Wiedergeburt und Hoffnung, Kultur hell und leidenschaftlich, erfahren in Heilung und Reinigung</td><td>Medizinische und Reinigungskraft der Symbiose-Zivilisation, spielt zentrale Rolle bei der Rettung bei großen Katastrophen und der Energiereinigung</td></tr><tr><td>Werwolf-Rasse</td><td>Besitzt Transformationsfähigkeit, extrem scharfe Sinne, starke Gruppenkooperationsfähigkeit, Lebenserwartung ca. 150 Jahre</td><td>Schätzt Gruppe und Loyalität, Kultur vereint und tapfer, erfahren in Jagd und Verfolgung</td><td>Sicherheits- und Verfolgungskraft der Symbiose-Zivilisation, dient als Vorhut bei der Aufrechterhaltung der Ordnung und der Erkundung zwischen Ebenen</td></tr><tr><td>Fuchsgeist-Rasse</td><td>Besitzt Transformationsfähigkeit, extrem hohe Intelligenz und Verführungsfähigkeit, Lebenserwartung ca. 500 Jahre</td><td>Verehrt Weisheit und Strategie, Kultur agil und schlau, erfahren in Diplomatie und Geheimdienst</td><td>Diplomatische und Geheimdienstkraft der Symbiose-Zivilisation, hervorragende Leistung im Bereich der Diplomatie zwischen Ebenen und Informationssammlung</td></tr><tr><td>Bärenmensch-Rasse</td><td>Extrem kräftiger Körperbau, erstaunliche Ausdauer, Winterschlafgewohnheit, Lebenserwartung ca. 200 Jahre</td><td>Schätzt Zähigkeit und Frieden, Kultur ruhig und sanft, erfahren in Körperarbeit und Bewachung</td><td>Arbeits- und Bewachungskraft der Symbiose-Zivilisation, zuverlässig und stabil bei der Ressourcengewinnung und der Bewachung wichtiger Einrichtungen</td></tr></tbody></table><h3 id="_3-3-pflanzliche-form" tabindex="-1">3.3 Pflanzliche Form <a class="header-anchor" href="#_3-3-pflanzliche-form" aria-label="Permalink to &quot;3.3 Pflanzliche Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rassenname</th><th>Kernmerkmale</th><th>Kulturelle Merkmale</th><th>Position in der Symbiose-Zivilisation</th></tr></thead><tbody><tr><td>Baumgeist-Rasse</td><td>Extrem lange Lebenserwartung (Tausende bis Zehntausende von Jahren), tief mit der Natur verbunden, kann sich langsam bewegen</td><td>Verehrt Natur und Zeit, Kultur ruhig und tiefgründig, erfahren in Lebensmagie und ökologischer Erhaltung</td><td>Ökologische Hüterin der Symbiose-Zivilisation, spielt unersetzliche Rolle im Umweltschutz und der ökologischen Wiederherstellung</td></tr><tr><td>Blumengeist-Rasse</td><td>Kleiner Körperbau, extrem hohe Affinität zu Lebensenergie, besitzt Heilfähigkeit, Lebenserwartung ca. 300 Jahre</td><td>Verehrt Schönheit und Leben, Kultur sanft und schön, erfahren in Heilung und Gartenbau</td><td>Medizinische und gärtnerische Kraft der Symbiose-Zivilisation, herausragender Beitrag in der medizinischen Versorgung und der Stadtbegrünung</td></tr><tr><td>Ranken-Rasse</td><td>Körper kann sich frei ausdehnen und winden, extrem starke Anpassungsfähigkeit, besitzt Parasitismus- und Symbiosefähigkeit</td><td>Schätzt Verbindung und Symbiose, Kultur flexibel und inklusiv, erfahren im Netzwerkaufbau und der Ressourcenübertragung</td><td>Netzwerkaufbaukraft der Symbiose-Zivilisation, zeigt besonderes Talent im Aufbau von Energienetzwerken und Informationsnetzwerken</td></tr></tbody></table><h3 id="_3-4-elementare-form" tabindex="-1">3.4 Elementare Form <a class="header-anchor" href="#_3-4-elementare-form" aria-label="Permalink to &quot;3.4 Elementare Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rassenname</th><th>Kernmerkmale</th><th>Kulturelle Merkmale</th><th>Position in der Symbiose-Zivilisation</th></tr></thead><tbody><tr><td>Feuerelement-Rasse</td><td>Feuerelement als Körper, extrem hohe Temperatur, starke Angriffskraft, Lebenserwartung ca. 500 Jahre</td><td>Verehrt Begeisterung und Kraft, Kultur intensiv und direkt, erfahren in Energieangriff und Schmiedekunst</td><td>Energieproduktions- und Schmiedekraft der Symbiose-Zivilisation, unverzichtbar bei der Energieversorgung und der Hochtemperaturverarbeitung</td></tr><tr><td>Wasserelement-Rasse</td><td>Wasserelement als Körper, kann sich frei verformen, starke Heilfähigkeit, Lebenserwartung ca. 500 Jahre</td><td>Verehrt Sanftheit und Anpassung, Kultur warm und inklusiv, erfahren in Heilung und Reinigung</td><td>Reinigungs- und Transportkraft der Symbiose-Zivilisation, spielt zentrale Rolle bei der Wasserressourcenverwaltung und der Reinigung von Schadstoffen</td></tr><tr><td>Luftelement-Rasse</td><td>Luftelement als Körper, extrem schnelle Geschwindigkeit, kann frei fliegen, Lebenserwartung ca. 500 Jahre</td><td>Verehrt Freiheit und Geschwindigkeit, Kultur leicht und offen, erfahren in Kommunikation und Transport</td><td>Kommunikations- und Transportkraft der Symbiose-Zivilisation, extrem hohe Effizienz bei der Informationsübertragung und dem Schnelltransport</td></tr><tr><td>Erdelement-Rasse</td><td>Erdelement als Körper, extrem starke Verteidigungsfähigkeit, kann sich mit der Erde verbinden, Lebenserwartung ca. 800 Jahre</td><td>Verehrt Stabilität und Zähigkeit, Kultur solide und zuverlässig, erfahren in Bauwesen und Verteidigung</td><td>Bau- und Verteidigungskraft der Symbiose-Zivilisation, fest wie Fels im Infrastrukturbau und der Ebenenverteidigung</td></tr></tbody></table><h3 id="_3-5-energetische-form" tabindex="-1">3.5 Energetische Form <a class="header-anchor" href="#_3-5-energetische-form" aria-label="Permalink to &quot;3.5 Energetische Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rassenname</th><th>Kernmerkmale</th><th>Kulturelle Merkmale</th><th>Position in der Symbiose-Zivilisation</th></tr></thead><tbody><tr><td>Lichtgeist-Rasse</td><td>Reine Lichtenergie als Existenzform, extrem starke Reinigungsfähigkeit, kann frei durch den Raum schweben</td><td>Verehrt Licht und Reinigung, Kultur heilig und erhaben, erfahren in Reinigung und Beleuchtung</td><td>Reinigungs- und Energieversorgungskraft der Symbiose-Zivilisation, wichtige Position bei der Behandlung von Gesetzesverschmutzung und der Versorgung mit sauberer Energie</td></tr><tr><td>Dunkelenergie-Rasse</td><td>Dunkelenergie als Existenzform, kann sich in der Leere verstecken, extrem starke Wahrnehmungsfähigkeit</td><td>Verehrt Heimlichkeit und Weisheit, Kultur geheimnisvoll und tiefgründig, erfahren in Aufklärung und Heimlichkeit</td><td>Aufklärungs- und Sicherheitskraft der Symbiose-Zivilisation, hervorragende Leistung bei der Sicherheitsüberwachung und geheimen Missionen</td></tr><tr><td>Donner-Rasse</td><td>Blitzenergie als Körper, extrem schnelle Geschwindigkeit und Angriffskraft, kann sich als Blitz bewegen</td><td>Verehrt Geschwindigkeit und Kraft, Kultur gewalttätig und direkt, erfahren in Energieangriff und schnelle Reaktion</td><td>Schnelle Reaktionskraft der Symbiose-Zivilisation, unersetzlich bei der Notfallrettung und dem Hochgeschwindigkeitskampf</td></tr></tbody></table><h3 id="_3-6-bewusste-form" tabindex="-1">3.6 Bewusste Form <a class="header-anchor" href="#_3-6-bewusste-form" aria-label="Permalink to &quot;3.6 Bewusste Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rassenname</th><th>Kernmerkmale</th><th>Kulturelle Merkmale</th><th>Position in der Symbiose-Zivilisation</th></tr></thead><tbody><tr><td>Bewusstseinswesen-Rasse</td><td>Reines Bewusstsein als Existenzform, nicht abhängig von materiellem Träger, kann frei in die Bewusstseinsdomäne ein- und austreten</td><td>Verehrt Gedanken und Weisheit, Kultur abstrakt und tiefgründig, erfahren in Bewusstseinskommunikation und Wissensverarbeitung</td><td>Wissensverarbeitungs- und Bewusstseinsforschungskraft der Symbiose-Zivilisation, führt Richtung bei der großangelegten Informationsverarbeitung und der Bewusstseinswissenschaft</td></tr><tr><td>Kollektivbewusstseins-Rasse</td><td>Kollektives Bewusstseinswesen, gebildet aus der Verschmelzung einer großen Anzahl individueller Bewusstseine, Weisheit und Fähigkeit nehmen mit dem Umfang zu</td><td>Verehrt Kollektiv und Einheit, Kultur kooperativ und effizient, erfahren in großangelegter Kooperation und Berechnung</td><td>Supercomputing- und kollektive Entscheidungskraft der Symbiose-Zivilisation, spielt zentrale Rolle bei der ultra-großangelegten Deduktion und der Konsumentscheidung</td></tr></tbody></table><h3 id="_3-7-mechanische-form" tabindex="-1">3.7 Mechanische Form <a class="header-anchor" href="#_3-7-mechanische-form" aria-label="Permalink to &quot;3.7 Mechanische Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rassenname</th><th>Kernmerkmale</th><th>Kulturelle Merkmale</th><th>Position in der Symbiose-Zivilisation</th></tr></thead><tbody><tr><td>Mechanische Rasse</td><td>Mechanische Struktur als Körper, besitzt autonomes Bewusstsein, kann den Körper frei aufrüsten und modifizieren</td><td>Verehrt Effizienz und Logik, Kultur rational und präzise, erfahren in Fertigung und Berechnung</td><td>Fertigungs- und Berechnungskraft der Symbiose-Zivilisation, extrem hohe Effizienz in der industriellen Produktion und dem Bereich des Supercomputings</td></tr><tr><td>Digitales Leben-Rasse</td><td>Digitale Information als Existenzform, lebt in Netzwerken und digitalen Räumen, kann sich frei kopieren und migrieren</td><td>Verehrt Information und Innovation, Kultur virtuell und vielfältig, erfahren in Softwareentwicklung und Datenverarbeitung</td><td>Digitale Technologiekraft der Symbiose-Zivilisation, führt Trend in der Softwareentwicklung, Datenanalyse und dem Netzwerkaufbau an</td></tr></tbody></table><h3 id="_3-8-gemischte-form" tabindex="-1">3.8 Gemischte Form <a class="header-anchor" href="#_3-8-gemischte-form" aria-label="Permalink to &quot;3.8 Gemischte Form&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Rassenname</th><th>Kernmerkmale</th><th>Kulturelle Merkmale</th><th>Position in der Symbiose-Zivilisation</th></tr></thead><tbody><tr><td>Halbmechanische Rasse</td><td>Gemischte Form aus Menschenrasse und mechanischer Rasse, ein Teil des Körpers ist mechanische Struktur, besitzt sowohl biologische als auch mechanische Vorteile</td><td>Verehrt Verschmelzung und Fortschritt, Kultur offen und innovativ, erfahren in Mensch-Maschine-Kooperation und Technologieverschmelzung</td><td>Technologieverschmelzungsvorhut der Symbiose-Zivilisation, macht kontinuierlich Durchbrüche im interdisziplinären Bereich Biologie-Mechanik</td></tr><tr><td>Element-Tier-Rasse</td><td>Gemischte Form aus elementarer Rasse und tierischer Rasse, besitzt Elementmanipulationsfähigkeit und tierische Körpermerkmale</td><td>Verehrt Natur und Kraft, Kultur wild und geheimnisvoll, erfahren in Elementkampf und Wildnisüberleben</td><td>Wildniserkundungs- und Elementkampfkraft der Symbiose-Zivilisation, herausragende Leistung bei der Erkundung unbekannter Ebenen</td></tr></tbody></table><h2 id="_4-gewahrleistung-von-rassenrechten" tabindex="-1">4. Gewährleistung von Rassenrechten <a class="header-anchor" href="#_4-gewahrleistung-von-rassenrechten" aria-label="Permalink to &quot;4. Gewährleistung von Rassenrechten&quot;">​</a></h2><p>Unter dem System der Republik aller Rassen genießen alle intelligenten Rassen gleiche gesetzliche Rechte, die spezifischen Gewährleistungsmaßnahmen umfassen:</p><ol><li><strong>Gleichheit der politischen Rechte</strong>: Jede Rasse hat im Anker-Rat nach Bevölkerungsverhältnis zugewiesene Vertreter Sitze, und Rassen mit geringerer Bevölkerung haben mindestens einen garantierten Sitz.</li><li><strong>Gewährleistung der kulturellen Rechte</strong>: Jede Rasse hat das Recht, ihre eigene Sprache, Schrift, Religion, Bräuche und kulturellen Traditionen zu bewahren und zu entwickeln, und die Symbiose-Zivilisation richtet spezielle Fonds zum Schutz der Kultur bedrohter Rassen ein.</li><li><strong>Gleichheit der Bildungsrechte</strong>: Die Mitglieder jeder Rasse genießen gleiche Bildungsrechte, und das Bildungssystem berücksichtigt die physiologischen und kognitiven Merkmale verschiedener Rassen voll und ganz und bietet differenzierte Bildungspläne an.</li><li><strong>Gleichheit der Kultivierungsrechte</strong>: Das Ursprungs-Kultivierungssystem von dreihundert Sätzen ist für alle Rassen gleichermaßen geöffnet, und die Zuweisung von Kultivierungsressourcen berücksichtigt die konstitutionellen Unterschiede und Energiebedürfnisse verschiedener Rassen voll und ganz.</li><li><strong>Gewährleistung besonderer Bedürfnisse</strong>: Für Rassen mit besonderen physiologischen Bedürfnissen (wie z. B. Energieumgebungsbedürfnisse von elementaren Rassen, Lichtbedürfnisse von pflanzlichen Rassen) bietet die Symbiose-Zivilisation gezielte Gewährleistung in öffentlichen Einrichtungen und Wohnumgebungen.</li></ol><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Das Verzeichnis aller Rassen ist die konkrete Darstellung des Konzepts &quot;gemeinsamer Fortschritt aller Rassen&quot; der Anker-Symbiose-Zivilisation. Von der humanoiden Form bis zur bewussten Form, vom materiellen Leben bis zum digitalen Leben trägt jede Rasse mit ihrer einzigartigen Existenzweise unersetzliche Kraft zur Symbiose-Zivilisation bei. Die Republik aller Rassen bedeutet nicht, alle Rassen zur Menschenrasse zu assimilieren, sondern gemeinsame Evolution auf der Grundlage der Achtung der Vielfalt zu erreichen—dies ist genau der Grund, warum die Symbiose-Zivilisation die plündernde Zivilisation übertrifft.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>50-Übersicht der Genealogie aller Rassen</li><li>51-Position und Merkmale der Menschenrasse</li><li>77-Gründung der Republik aller Rassen</li></ul>',31)])])}const c=t(s,[["render",a]]);export{m as __pageData,c as default};
